        </div>

        <div class="task-section">
            <div class="task-section-title">📋 任务列表</div>
            <div class="task-input-row">
                <input type="text" class="task-input" id="taskInput" placeholder="添加新任务…" maxlength="120" autocomplete="off">
                <button class="btn-add-task" id="btnAddTask">添加</button>
            </div>
