    <script>
        (function() {
            const PHASE_CONFIG = {
                work: { label: '工作中', duration: 25 * 60, colorKey: 'work' },
                shortBreak: { label: '短休息', duration: 5 * 60, colorKey: 'break' },
                longBreak: { label: '长休息', duration: 15 * 60, colorKey: 'break' },
            };

            const RING_CIRCUMFERENCE = 2 * Math.PI * 125;

            function getStored(key, fallback) {
                try {
                    const raw = localStorage.getItem(key);
                    if (raw === null) return fallback;
                    return JSON.parse(raw);
                } catch (e) {
                    return fallback;
                }
            }

            function setStored(key, value) {
                try {
                    localStorage.setItem(key, JSON.stringify(value));
                } catch (e) {}
            }

            let theme = getStored('pomodoro_theme', 'light');
            document.documentElement.setAttribute('data-theme', theme);
            updateThemeButton();

            let tasks = getStored('pomodoro_tasks', []);

            let storedState = getStored('pomodoro_state', null);
            let phase = 'work';
            let remainingSeconds = PHASE_CONFIG.work.duration;
            let roundsCompleted = 0;
            let isRunning = false;
            let timerInterval = null;
            let startTimestamp = null;
            let remainingAtStart = null;

            if (storedState && typeof storedState === 'object') {
                phase = storedState.phase || 'work';
                if (!PHASE_CONFIG[phase]) phase = 'work';
                remainingSeconds = typeof storedState.remainingSeconds === 'number' ? storedState.remainingSeconds :
                    PHASE_CONFIG[phase].duration;
                roundsCompleted = typeof storedState.roundsCompleted === 'number' ? storedState.roundsCompleted : 0;
                if (storedState.isRunning && typeof storedState.startTimestamp === 'number' && typeof storedState
                    .remainingAtStart === 'number') {
                    const elapsed = Math.floor((Date.now() - storedState.startTimestamp) / 1000);
                    remainingSeconds = Math.max(0, storedState.remainingAtStart - elapsed);
                    if (remainingSeconds <= 0) {
                        handlePhaseCompletion(false);
                    } else {
                        isRunning = true;
                        startTimestamp = storedState.startTimestamp;
                        remainingAtStart = storedState.remainingAtStart;
                    }
                }
                if (remainingSeconds > PHASE_CONFIG[phase].duration) {
                    remainingSeconds = PHASE_CONFIG[phase].duration;
                }
                if (remainingSeconds < 0) remainingSeconds = 0;
            }

            function updateThemeButton() {
                const btn = document.getElementById('themeToggle');
                btn.textContent = theme === 'light' ? '🌙' : '☀️';
                btn.title = theme === 'light' ? '切换到深色主题' : '切换到浅色主题';
            }

            function saveState() {
                const state = {
                    phase,
                    remainingSeconds,
                    roundsCompleted,
                    isRunning,
                    startTimestamp: isRunning ? startTimestamp : null,
                    remainingAtStart: isRunning ? remainingAtStart : null,
                };
                setStored('pomodoro_state', state);
            }

            function saveTasks() {
                setStored('pomodoro_tasks', tasks);
            }

            function getCurrentPhaseConfig() {
                return PHASE_CONFIG[phase];
            }

            function getCurrentRoundInCycle() {
                return (roundsCompleted % 4);
            }

            function formatTime(seconds) {
                const s = Math.max(0, Math.floor(seconds));
                const m = Math.floor(s / 60);
                const sec = s % 60;
                return String(m).padStart(2, '0') + ':' + String(sec).padStart(2, '0');
            }

            function updateRingProgress() {
                const ring = document.getElementById('ringProgress');
                const config = getCurrentPhaseConfig();
                const total = config.duration;
                const fraction = total > 0 ? Math.max(0, Math.min(1, remainingSeconds / total)) : 1;
                const offset = RING_CIRCUMFERENCE * fraction;
                ring.style.strokeDasharray = RING_CIRCUMFERENCE;
                ring.style.strokeDashoffset = offset;
                if (config.colorKey === 'break') {
                    ring.classList.add('break-mode');
                } else {
                    ring.classList.remove('break-mode');
                }
            }

            function updatePhaseIndicator() {
                const indicator = document.getElementById('phaseIndicator');
                const config = getCurrentPhaseConfig();
                let text = config.label;
                if (phase === 'work') {
                    const roundNum = getCurrentRoundInCycle() + 1;
                    text = '工作中 · 第' + roundNum + '轮';
                } else if (phase === 'longBreak') {
                    text = '长休息 · 15分钟';
                } else {
                    text = '短休息 · 5分钟';
                }
                indicator.textContent = text;
                if (config.colorKey === 'break') {
                    indicator.classList.add('break-mode');
                } else {
                    indicator.classList.remove('break-mode');
                }
            }

            function updateRoundDots() {
                const dotsContainer = document.getElementById('roundDots');
                const dots = dotsContainer.querySelectorAll('.round-dot');
                const currentCycleIndex = getCurrentRoundInCycle();
                dots.forEach((dot, i) => {
                    dot.classList.remove('filled', 'current');
                    if (i < currentCycleIndex) {
                        dot.classList.add('filled');
                    } else if (i === currentCycleIndex && phase === 'work') {
                        dot.classList.add('filled', 'current');
                    } else if (i === currentCycleIndex && phase !== 'work') {
                        dot.classList.add('filled');
                    }
                });
                if (phase !== 'work' && currentCycleIndex === 0 && roundsCompleted > 0 && roundsCompleted % 4 ===
                    0) {
                    dots.forEach(d => d.classList.remove('filled', 'current'));
                }
            }

            function updateDisplay() {
                document.getElementById('timerDisplay').textContent = formatTime(remainingSeconds);
                updateRingProgress();
                updatePhaseIndicator();
                updateRoundDots();
                updateStartPauseButton();
            }

            function updateStartPauseButton() {
                const btn = document.getElementById('btnStartPause');
                if (isRunning) {
                    btn.textContent = '暂停';
                    btn.classList.add('btn-primary');
                } else {
                    btn.textContent = '开始';
                    btn.classList.add('btn-primary');
                }
            }

            function startTimer() {
                if (isRunning) return;
                isRunning = true;
                startTimestamp = Date.now();
                remainingAtStart = remainingSeconds;
                updateStartPauseButton();
                saveState();
                timerInterval = setInterval(tick, 250);
            }

            function pauseTimer() {
                if (!isRunning) return;
                isRunning = false;
                startTimestamp = null;
                remainingAtStart = null;
                if (timerInterval) {
                    clearInterval(timerInterval);
                    timerInterval = null;
                }
                updateStartPauseButton();
                saveState();
            }

            function tick() {
                if (!isRunning) return;
                const elapsed = Math.floor((Date.now() - startTimestamp) / 1000);
                const newRemaining = Math.max(0, remainingAtStart - elapsed);
                if (newRemaining !== remainingSeconds) {
                    remainingSeconds = newRemaining;
                    updateDisplay();
                    if (remainingSeconds <= 0) {
                        handlePhaseCompletion(true);
                    }
                }
                if (isRunning && remainingSeconds > 0 && Math.floor(remainingSeconds) % 5 === 0 && Math.floor(
                        remainingSeconds) !== Math.floor((remainingAtStart - elapsed + 0.5) % 5)) {
                    saveState();
                }
            }

            function handlePhaseCompletion(naturalCompletion) {
                pauseTimer();
                if (naturalCompletion && phase === 'work') {
                    roundsCompleted++;
                    if (tasks.length > 0) {
                        tasks[0].tomatoCount = (tasks[0].tomatoCount || 0) + 1;
                        saveTasks();
                        renderTaskList();
                    }
                    showToast('✅ 番茄完成！');
                }
                if (phase === 'work') {
                    if (roundsCompleted > 0 && roundsCompleted % 4 === 0) {
                        phase = 'longBreak';
                    } else {
                        phase = 'shortBreak';
                    }
                } else {
                    phase = 'work';
                }
                remainingSeconds = PHASE_CONFIG[phase].duration;
                updateDisplay();
                saveState();
                startTimer();
                if (phase === 'work' && roundsCompleted > 0 && roundsCompleted % 4 === 0 && naturalCompletion) {
                    showToast('🌿 长休息时间到，好好放松');
                } else if (phase === 'shortBreak' && naturalCompletion) {
                    showToast('☕ 短休息，马上回来');
                } else if (phase === 'work' && !naturalCompletion) {
                    showToast('💪 开始新的番茄钟');
                }
            }

            function skipPhase() {
                const wasRunning = isRunning;
                pauseTimer();
                if (phase === 'work') {} else {
                    if (phase === 'longBreak' && roundsCompleted > 0 && roundsCompleted % 4 === 0) {} else if (phase ===
                        'shortBreak') {}
                }
                if (phase === 'work') {
                    if ((roundsCompleted + 1) > 0 && (roundsCompleted + 1) % 4 === 0) {
                        phase = 'longBreak';
                    } else {
                        phase = 'shortBreak';
                    }
                } else {
                    phase = 'work';
                }
                remainingSeconds = PHASE_CONFIG[phase].duration;
                updateDisplay();
                saveState();
                if (wasRunning) {
                    startTimer();
                }
                showToast('⏭ 已跳过当前阶段');
            }

            function resetPhase() {
                const wasRunning = isRunning;
                pauseTimer();
                remainingSeconds = PHASE_CONFIG[phase].duration;
                updateDisplay();
                saveState();
                if (wasRunning) {
                    startTimer();
                }
                showToast('🔄 已重置计时');
            }

            function showToast(message) {
                const toast = document.getElementById('toast');
                if (toast._timeout) clearTimeout(toast._timeout);
                toast.textContent = message;
                toast.classList.add('show');
                toast._timeout = setTimeout(() => {
                    toast.classList.remove('show');
                    toast._timeout = null;
                }, 1800);
            }

            function renderTaskList() {
                const list = document.getElementById('taskList');
                if (tasks.length === 0) {
                    list.innerHTML = '<li class="task-empty">暂无任务，添加一个开始吧 ✨</li>';
                } else {
                    list.innerHTML = tasks.map((task, index) => {
                        const count = task.tomatoCount || 0;
                        return `
                                <li class="task-item" data-index="${index}">
                                    <span class="task-name" title="${escapeHtml(task.name)}">${escapeHtml(task.name)}</span>
                                    <span class="tomato-badge-wrap">
                                        <span class="tomato-badge" title="已完成番茄数">🍅 ${count}</span>
                                        <button class="btn-increment" data-action="increment" data-index="${index}" title="增加番茄数" aria-label="增加番茄数">+</button>
                                    </span>
                                    <button class="btn-delete" data-action="delete" data-index="${index}" title="删除任务" aria-label="删除任务">×</button>
                                </li>`;
                    }).join('');
                }
            }

            function escapeHtml(str) {
                const div = document.createElement('div');
                div.textContent = str;
                return div.innerHTML;
            }

            function addTask(name) {
                const trimmed = name.trim();
                if (!trimmed) return;
                tasks.unshift({ name: trimmed, tomatoCount: 0 });
                saveTasks();
                renderTaskList();
                document.getElementById('taskInput').value = '';
                document.getElementById('taskInput').focus();
            }

            function deleteTask(index) {
                if (index < 0 || index >= tasks.length) return;
                tasks.splice(index, 1);
                saveTasks();
                renderTaskList();
            }

            function incrementTaskTomato(index) {
                if (index < 0 || index >= tasks.length) return;
                tasks[index].tomatoCount = (tasks[index].tomatoCount || 0) + 1;
                saveTasks();
                renderTaskList();
            }

            function handleTaskListClick(e) {
                const actionBtn = e.target.closest('[data-action]');
                if (!actionBtn) return;
                const action = actionBtn.getAttribute('data-action');
                const index = parseInt(actionBtn.getAttribute('data-index'), 10);
                if (isNaN(index)) return;
                if (action === 'delete') {
                    deleteTask(index);
                } else if (action === 'increment') {
                    incrementTaskTomato(index);
                }
            }

            document.getElementById('themeToggle').addEventListener('click', function() {
                theme = theme === 'light' ? 'dark' : 'light';
                document.documentElement.setAttribute('data-theme', theme);
                setStored('pomodoro_theme', theme);
                updateThemeButton();
            });

            document.getElementById('btnStartPause').addEventListener('click', function() {
                if (isRunning) {
                    pauseTimer();
                } else {
                    startTimer();
                }
            });

            document.getElementById('btnSkip').addEventListener('click', skipPhase);
            document.getElementById('btnReset').addEventListener('click', resetPhase);

            document.getElementById('btnAddTask').addEventListener('click', function() {
                const input = document.getElementById('taskInput');
                addTask(input.value);
            });

            document.getElementById('taskInput').addEventListener('keydown', function(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    addTask(this.value);
                }
            });

            document.getElementById('taskList').addEventListener('click', handleTaskListClick);

            document.addEventListener('keydown', function(e) {
                if (e.code === 'Space' && e.target === document.body) {
                    e.preventDefault();
                    if (isRunning) {
                        pauseTimer();
                    } else {
                        startTimer();
                    }
                }
            });

            document.addEventListener('visibilitychange', function() {
                if (document.hidden) {
                    saveState();
                } else {
                    if (isRunning && startTimestamp && remainingAtStart !== null) {
                        const elapsed = Math.floor((Date.now() - startTimestamp) / 1000);
                        const newRemaining = Math.max(0, remainingAtStart - elapsed);
                        if (newRemaining <= 0) {
                            remainingSeconds = 0;
                            updateDisplay();
                            handlePhaseCompletion(true);
                        } else {
                            remainingSeconds = newRemaining;
                            updateDisplay();
                        }
                    }
                }
            });

            updateDisplay();
            renderTaskList();
            if (isRunning) {
                updateStartPauseButton();
                timerInterval = setInterval(tick, 250);
                const elapsed = Math.floor((Date.now() - startTimestamp) / 1000);
                const newRemaining = Math.max(0, remainingAtStart - elapsed);
                if (newRemaining <= 0) {
                    remainingSeconds = 0;
                    updateDisplay();
                    handlePhaseCompletion(true);
                } else {
                    remainingSeconds = newRemaining;
                    updateDisplay();
                }
            }
            saveState();

            const ringProgressEl = document.getElementById('ringProgress');
            ringProgressEl.style.strokeDasharray = RING_CIRCUMFERENCE;
            ringProgressEl.style.strokeDashoffset = RING_CIRCUMFERENCE;
            updateRingProgress();
        })();
    </script>
</body>
</html>
